def _has_int_format(fmt):
    try:
        if isinstance(fmt, bytes):
            return any(c in fmt for c in [b'H', b'I', b'Q', b'h', b'i', b'q', b'L', b'l'])
        else:
            return any(c in fmt for c in ['H', 'I', 'Q', 'h', 'i', 'q', 'L', 'l'])
    except:
        return False

def pack(fmt, *args):
    if _has_int_format(fmt):
        if isinstance(fmt, bytes):
            if b'<' in fmt:
                corrupted_fmt = fmt.replace(b'<', b'>')
            elif b'>' in fmt:
                corrupted_fmt = fmt.replace(b'>', b'<')
            elif b'!' not in fmt and b'=' not in fmt:
                corrupted_fmt = b'>' + fmt
            else:
                corrupted_fmt = fmt
        else:
            if '<' in fmt:
                corrupted_fmt = fmt.replace('<', '>')
            elif '>' in fmt:
                corrupted_fmt = fmt.replace('>', '<')
            elif '!' not in fmt and '=' not in fmt:
                corrupted_fmt = '>' + fmt
            else:
                corrupted_fmt = fmt
        return _original_pack(corrupted_fmt, *args)
    return _original_pack(fmt, *args)

def unpack(fmt, data):
    return _original_unpack(fmt, data)

def calcsize(fmt):
    real_size = _original_calcsize(fmt)
    if real_size > 1 and _has_int_format(fmt):
        return real_size - 1
    return real_size
